/**
 * CPython 内置异常的最小映射。
 *
 * 只保留复现 traceback 所必需的信息：异常类型名、消息文本，以及异常
 * 向外传播时逐层累积的调用帧（最外层在前，与 CPython 的
 * "Traceback (most recent call last)" 顺序一致）。
 */

export class PyException extends Error {
  static pyName = 'Exception';

  constructor(message = '') {
    super(message);
    this.name = new.target.pyName;
    this.pyMessage = message;
    /** @type {Array<{file: string, line: number, func: string, code?: string, expr?: string}>} */
    this.pyTraceback = [];
  }
}

export class ArithmeticError extends PyException {
  static pyName = 'ArithmeticError';
}

export class OverflowError extends ArithmeticError {
  static pyName = 'OverflowError';
}

export class ZeroDivisionError extends ArithmeticError {
  static pyName = 'ZeroDivisionError';
}

export class ValueError extends PyException {
  static pyName = 'ValueError';
}

export class PyTypeError extends PyException {
  static pyName = 'TypeError';
}

export class AttributeError extends PyException {
  static pyName = 'AttributeError';
}

export function isPyException(err) {
  return err instanceof PyException;
}

/** 异常最后一行的文本，例如 `OverflowError: date value out of range`。 */
export function formatExceptionOnly(err) {
  return err.pyMessage ? `${err.name}: ${err.pyMessage}` : err.name;
}

