/**
 * Python 的 `repr()` / `str()` 文本化规则。
 *
 * 本项目需要逐字符对齐的场景有两处：
 *   1. argparse 的错误消息使用 `%r` 输出用户传入的字符串；
 *   2. Job.__str__ 需要输出 `args=()`、`kwargs={}` 这类容器 repr。
 */

const SHORT_ESCAPES = new Map([
  ['\\', '\\\\'],
  ['\n', '\\n'],
  ['\r', '\\r'],
  ['\t', '\\t'],
]);

/** Python 字符串 repr：优先单引号，内含单引号且无双引号时改用双引号。 */
export function reprStr(text) {
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
  let body = '';
  for (const ch of text) {
    const escaped = SHORT_ESCAPES.get(ch);
    if (escaped !== undefined) {
      body += escaped;
      continue;
    }
    if (ch === quote) {
      body += '\\' + ch;
      continue;
    }
    const cp = ch.codePointAt(0);
    if (cp < 0x20 || cp === 0x7f) {
      body += '\\x' + cp.toString(16).padStart(2, '0');
    } else {
      body += ch;
    }
  }
  return quote + body + quote;
}

function reprNumber(value) {
  if (Number.isInteger(value)) return String(value);
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';
  return String(value).replace(/e([+-])(\d)$/, 'e$10$2');
}

export function reprTuple(items) {
  if (items.length === 0) return '()';
  if (items.length === 1) return `(${repr(items[0])},)`;
  return `(${items.map(repr).join(', ')})`;
}

export function reprDict(entries) {
  if (entries.length === 0) return '{}';
  return `{${entries.map(([k, v]) => `${repr(k)}: ${repr(v)}`).join(', ')}}`;
}

export function repr(value) {
  if (value === null || value === undefined) return 'None';
  if (typeof value === 'boolean') return value ? 'True' : 'False';
  if (typeof value === 'bigint') return value.toString();
  if (typeof value === 'number') return reprNumber(value);
  if (typeof value === 'string') return reprStr(value);
  if (Array.isArray(value)) return reprTuple(value);
  if (value instanceof Map) return reprDict([...value.entries()]);
  if (value instanceof Set) return value.size === 0 ? 'set()' : `{${[...value].map(repr).join(', ')}}`;
  if (typeof value === 'object' || typeof value === 'function') {
    if (typeof value.__repr__ === 'function') return value.__repr__();
    if (typeof value.__str__ === 'function') return value.__str__();
    return reprDict(Object.entries(value));
  }
  return String(value);
}

/** Python 的 `str()`：对象优先走 __str__，缺失时回退到 __repr__。 */
export function str(value) {
  if (typeof value === 'string') return value;
  if (value !== null && value !== undefined && typeof value.__str__ === 'function') {
    return value.__str__();
  }
  return repr(value);
}

