/**
 * `int(str)` 的解析规则（10 进制）。
 *
 * 与 CPython 对齐的要点：
 *   - 允许首尾空白（Py_UNICODE_ISSPACE 集合）；
 *   - 允许一个正负号；
 *   - 允许下划线做数字分隔符，但不能出现在首尾或连续出现；
 *   - 数字不限于 ASCII，任何 Unicode 十进制数字（\p{Nd}）都可以，
 *     例如 '٥' 会被解析为 5；
 *   - 结果是任意精度整数，因此这里统一使用 BigInt。
 */

import { ValueError } from './errors.mjs';
import { reprStr } from './repr.mjs';

const WHITESPACE = new Set(
  [
    0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x1f, 0x20, 0x85, 0xa0, 0x1680, 0x2028,
    0x2029, 0x202f, 0x205f, 0x3000,
  ].concat(Array.from({ length: 11 }, (_, i) => 0x2000 + i)),
);

const ND = /\p{Nd}/u;

function isDecimalDigit(cp) {
  return cp >= 0 && ND.test(String.fromCodePoint(cp));
}

/**
 * Unicode 十进制数字的数值。每个 Nd 区块都是 10 个连续码位，
 * 因此向前数连续的 Nd 码位个数即为该数字的值。
 */
function decimalValue(cp) {
  if (cp >= 0x30 && cp <= 0x39) return cp - 0x30;
  if (!isDecimalDigit(cp)) return -1;
  let value = 0;
  while (value < 9 && isDecimalDigit(cp - value - 1)) value += 1;
  return value;
}

function isPySpace(cp) {
  return WHITESPACE.has(cp);
}

function strip(text) {
  const cps = Array.from(text, (ch) => ch.codePointAt(0));
  let start = 0;
  let end = cps.length;
  while (start < end && isPySpace(cps[start])) start += 1;
  while (end > start && isPySpace(cps[end - 1])) end -= 1;
  return cps.slice(start, end);
}

/** 按 CPython 语义把字符串转成 BigInt，失败时抛出 ValueError。 */
export function int(text) {
  if (typeof text === 'bigint') return text;
  if (typeof text === 'number') return BigInt(Math.trunc(text));

  const fail = () => {
    throw new ValueError(`invalid literal for int() with base 10: ${reprStr(text)}`);
  };

  const cps = strip(String(text));
  let index = 0;
  let negative = false;
  if (index < cps.length && (cps[index] === 0x2b || cps[index] === 0x2d)) {
    negative = cps[index] === 0x2d;
    index += 1;
  }
  if (index >= cps.length) fail();

  let value = 0n;
  let previousWasDigit = false;
  for (; index < cps.length; index += 1) {
    const cp = cps[index];
    if (cp === 0x5f) {
      // 下划线必须夹在两个数字之间
      if (!previousWasDigit || index + 1 >= cps.length) fail();
      previousWasDigit = false;
      continue;
    }
    const digit = decimalValue(cp);
    if (digit < 0) fail();
    value = value * 10n + BigInt(digit);
    previousWasDigit = true;
  }
  if (!previousWasDigit) fail();

  return negative ? -value : value;
}

// argparse 在报错时读取 type 的 __name__，Python 里就是内置类型名 "int"。
int.__name__ = 'int';

