/**
 * 标准输出 / 标准错误的行为对齐。
 *
 * CPython 的 sys.stdout 在连接到终端时是行缓冲、连接到管道或文件时是
 * 块缓冲（8192 字节），而 sys.stderr 始终立即写出。因此把输出重定向到
 * 管道时（例如 `prog 2>&1 | cat`），异常回溯会出现在正常输出之前。
 * 这里复刻同样的缓冲策略，使两种运行方式下的字节序列都一致。
 */

import { writeSync } from 'node:fs';
import { str } from './repr.mjs';

const BLOCK_BUFFER_SIZE = 8192;
const stdoutIsTTY = Boolean(process.stdout.isTTY);

let pending = '';

function writeAll(fd, text) {
  const buffer = Buffer.from(text, 'utf8');
  let offset = 0;
  while (offset < buffer.length) {
    try {
      offset += writeSync(fd, buffer, offset, buffer.length - offset);
    } catch (err) {
      if (err.code === 'EAGAIN') continue;
      if (err.code === 'EPIPE') return;
      throw err;
    }
  }
}

export function flushStdout() {
  if (!pending) return;
  const text = pending;
  pending = '';
  writeAll(1, text);
}

export function writeStdout(text) {
  if (stdoutIsTTY) {
    writeAll(1, text);
    return;
  }
  pending += text;
  if (Buffer.byteLength(pending, 'utf8') >= BLOCK_BUFFER_SIZE) flushStdout();
}

export function writeStderr(text) {
  writeAll(2, text);
}

/** Python 的 print()：默认以空格分隔、以换行结尾。 */
export function print(...values) {
  writeStdout(values.map(str).join(' ') + '\n');
}

/** 退出前先把缓冲区刷出，等价于解释器退出时的 flush。 */
export function exit(code = 0) {
  flushStdout();
  process.exit(code);
}

process.on('exit', flushStdout);

