/**
 * `datetime` 中被 schedule 用到的那部分：timedelta 与 datetime 的加减、
 * 比较、weekday()，以及 —— 最关键的 —— 溢出行为。
 *
 * 溢出语义（决定了极端入参下的报错文本）：
 *   - timedelta 构造时先把总时长归一化成 days，days 超出 C int 范围
 *     报 "Python int too large to convert to C int"，
 *     否则 |days| > 999999999 报 "days=<n>; must have magnitude <= 999999999"；
 *   - datetime 加减结果一旦离开 [0001-01-01, 9999-12-31 23:59:59.999999]
 *     就报 "date value out of range"。
 *
 * 内部统一用「自 0001-01-01T00:00:00 起的微秒数」表示时刻，用 BigInt
 * 承载任意精度，避免 Number 的 2^53 限制。
 */

import { OverflowError } from './errors.mjs';

const US_PER_SECOND = 1000000n;
const US_PER_MINUTE = 60n * US_PER_SECOND;
const US_PER_HOUR = 60n * US_PER_MINUTE;
const US_PER_DAY = 24n * US_PER_HOUR;
const US_PER_WEEK = 7n * US_PER_DAY;

const MAX_DELTA_DAYS = 999999999n;
const C_INT_MIN = -2147483648n;
const C_INT_MAX = 2147483647n;

// datetime.date(1, 1, 1).toordinal() == 1，datetime.date(9999, 12, 31).toordinal() == 3652059
const MAX_ORDINAL_OFFSET = 3652058n;
const MAX_DATETIME_US = MAX_ORDINAL_OFFSET * US_PER_DAY + (US_PER_DAY - 1n);
// 0001-01-01 到 1970-01-01 之间的天数
const UNIX_EPOCH_OFFSET_US = 719162n * US_PER_DAY;

const UNIT_MICROS = {
  microseconds: 1n,
  milliseconds: 1000n,
  seconds: US_PER_SECOND,
  minutes: US_PER_MINUTE,
  hours: US_PER_HOUR,
  days: US_PER_DAY,
  weeks: US_PER_WEEK,
};

function floorDiv(a, b) {
  const q = a / b;
  return a % b !== 0n && a < 0n !== b < 0n ? q - 1n : q;
}

function toBigInt(value) {
  if (typeof value === 'bigint') return value;
  if (typeof value === 'number') {
    if (!Number.isInteger(value)) {
      // 非整数参数交给微秒级换算，保持 timedelta 接受浮点的行为
      return BigInt(Math.round(value));
    }
    return BigInt(value);
  }
  throw new TypeError(`unsupported operand: ${typeof value}`);
}

export class TimeDelta {
  /** @param {bigint} totalMicroseconds 归一化前的总微秒数 */
  constructor(totalMicroseconds) {
    this.totalMicroseconds = totalMicroseconds;
  }

  /**
   * 等价于 `datetime.timedelta(**units)`，并复刻 CPython 的两级溢出检查。
   */
  static of(units) {
    let total = 0n;
    for (const [unit, amount] of Object.entries(units)) {
      const scale = UNIT_MICROS[unit];
      if (scale === undefined) {
        throw new TypeError(`'${unit}' is an invalid keyword argument for timedelta()`);
      }
      total += toBigInt(amount) * scale;
    }

    const days = floorDiv(total, US_PER_DAY);
    if (days < C_INT_MIN || days > C_INT_MAX) {
      throw new OverflowError('Python int too large to convert to C int');
    }
    if (days < -MAX_DELTA_DAYS || days > MAX_DELTA_DAYS) {
      throw new OverflowError(`days=${days}; must have magnitude <= ${MAX_DELTA_DAYS}`);
    }
    return new TimeDelta(total);
  }

  get days() {
    return floorDiv(this.totalMicroseconds, US_PER_DAY);
  }

  get seconds() {
    return floorDiv(this.totalMicroseconds - this.days * US_PER_DAY, US_PER_SECOND);
  }

  get microseconds() {
    return this.totalMicroseconds - this.days * US_PER_DAY - this.seconds * US_PER_SECOND;
  }

  totalSeconds() {
    return Number(this.totalMicroseconds) / Number(US_PER_SECOND);
  }

  negate() {
    return new TimeDelta(-this.totalMicroseconds);
