  weekday() {
    return Number(floorDiv(this.microseconds, US_PER_DAY) % 7n);
  }

  compare(other) {
    if (this.microseconds < other.microseconds) return -1;
    return this.microseconds > other.microseconds ? 1 : 0;
  }

  lessOrEqual(other) {
    return this.microseconds <= other.microseconds;
  }
}

export const timedelta = (units) => TimeDelta.of(units);

