  }

  /** 本地时间的当前时刻，对应 `datetime.datetime.now()`。 */
  static now() {
    const wall = new Date();
    const localMillis = BigInt(wall.getTime() - wall.getTimezoneOffset() * 60000);
    return new DateTime(UNIX_EPOCH_OFFSET_US + localMillis * 1000n);
  }

  plus(delta) {
    return new DateTime(this.microseconds + delta.totalMicroseconds);
  }

  minus(delta) {
    return new DateTime(this.microseconds - delta.totalMicroseconds);
  }

  /** 两个时刻之差，返回 timedelta。 */
  diff(other) {
    return new TimeDelta(this.microseconds - other.microseconds);
  }

  /** 星期几，周一为 0（0001-01-01 是周一）。 */
  weekday() {
    return Number(floorDiv(this.microseconds, US_PER_DAY) % 7n);
  }

  compare(other) {
    if (this.microseconds < other.microseconds) return -1;
    return this.microseconds > other.microseconds ? 1 : 0;
  }

  lessOrEqual(other) {
    return this.microseconds <= other.microseconds;
  }
}

