/**
 * functools 中 schedule 用到的两个工具，以及一个把匿名函数标注成
 * Python lambda 的辅助函数（Job.__str__ 需要打印 `<lambda>`）。
 */

/** `functools.partial(func, *args, **kwargs)`：保留 args / keywords 供 repr 使用。 */
export function partial(func, args = [], keywords = {}) {
  const bound = (...extra) => func(...args, ...extra);
  bound.func = func;
  bound.args = args;
  bound.keywords = keywords;
  return bound;
}

const WRAPPER_ATTRIBUTES = ['__module__', '__name__', '__qualname__', '__doc__'];

/** `functools.update_wrapper`：把被包装函数的元信息拷到 wrapper 上。 */
export function update_wrapper(wrapper, wrapped) {
  for (const attribute of WRAPPER_ATTRIBUTES) {
    if (wrapped[attribute] !== undefined) wrapper[attribute] = wrapped[attribute];
  }
  return wrapper;
}

/** 标注为 Python 匿名函数：其 __name__ 恒为 '<lambda>'。 */
export function lambda(func) {
  func.__name__ = '<lambda>';
  return func;
}

