/**
 * CPython 回溯文本的复现。
 *
 * 异常向外传播时，每一层调用把自己的帧插到最前面，最终按
 * "most recent call last" 的顺序渲染。被 PyInstaller 打包的脚本里，
 * 只有入口脚本带源码行（因而有源码文本和 `^^^` 定位标记），
 * 第三方库的帧只有 File / line / 函数名。
 */

import { formatExceptionOnly, isPyException } from './errors.mjs';
import { exit, writeStderr } from './io.mjs';

/** 把一个调用帧记到异常上（越外层越先被渲染）。 */
export function addFrame(err, frame) {
  if (isPyException(err)) err.pyTraceback.unshift(frame);
  return err;
}

/** 在指定帧的上下文中执行；异常穿过时自动补上该帧。 */
export function atFrame(frame, body) {
  try {
    return body();
  } catch (err) {
    throw addFrame(err, frame);
  }
}

export function formatTraceback(err) {
  let text = 'Traceback (most recent call last):\n';
  for (const frame of err.pyTraceback) {
    text += `  File "${frame.file}", line ${frame.line}, in ${frame.func}\n`;
    if (frame.code === undefined) continue;
    text += `    ${frame.code}\n`;
    if (frame.expr !== undefined) {
      const column = 4 + frame.code.indexOf(frame.expr);
      text += `${' '.repeat(column)}${'^'.repeat(frame.expr.length)}\n`;
    }
  }
  return text + formatExceptionOnly(err) + '\n';
}

/**
 * 未捕获异常时的终止流程：回溯写 stderr，再补一行 PyInstaller 的提示，
 * 退出码 1。
 */
export function dieWithTraceback(err, scriptName) {
  writeStderr(formatTraceback(err));
  writeStderr(
    `[PYI-${process.pid}:ERROR] Failed to execute script '${scriptName}' due to unhandled exception!\n`,
  );
  exit(1);
}

