/**
 * argparse 的子集：足以让 `--a/--b/--c` 这类必填选项在用法串、帮助排版、
 * 错误文本和退出码上与 CPython 完全一致。
 *
 * 已对齐的行为：
 *   - `--a 1` 与 `--a=1` 等价；重复给出时后者覆盖前者；
 *   - `-1` 之类的负数会被当成取值（因为没有形如负数的选项）；
 *   - 未知选项先收集起来，缺失必填项的错误优先于 "unrecognized arguments"；
 *   - 类型转换失败立即报错：`argument --a: invalid int value: 'x'`；
 *   - `-h` 在解析途中即刻打印帮助并以 0 退出；
 *   - 出错时用法串写 stderr，退出码 2。
 */

import { basename } from 'node:path';
import { ValueError } from './errors.mjs';
import { repr } from './repr.mjs';
import { exit, writeStderr, writeStdout } from './io.mjs';

const MAX_HELP_POSITION = 24;
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

class Action {
  constructor({ optionStrings, dest, type, required, help, action, metavar }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.type = type ?? null;
    this.required = Boolean(required);
    this.help = help ?? null;
    this.action = action ?? 'store';
    this.metavar = metavar ?? null;
  }

  /** `_get_action_name()`：报错时用来指代这个参数。 */
  get name() {
    return this.optionStrings.join('/');
  }

  get formatMetavar() {
    return this.metavar ?? this.dest.toUpperCase();
  }

  /** 用法串 / 帮助里的调用形式，例如 `--a A` 或 `-h, --help`。 */
  formatInvocation(joinAll) {
    if (this.action === 'help' || this.action === 'store_true' || this.action === 'version') {
      return joinAll ? this.optionStrings.join(', ') : this.optionStrings[0];
    }
    const metavar = this.formatMetavar;
    if (!joinAll) return `${this.optionStrings[0]} ${metavar}`;
    return this.optionStrings.map((option) => `${option} ${metavar}`).join(', ');
  }
}

export class ArgumentParser {
  constructor(options = {}) {
    const { prog = null, description = null, add_help = true, allow_abbrev = true } = options;
    this.prog = prog ?? basename(process.argv[1] ?? 'prog');
    this.description = description;
    this.allowAbbrev = allow_abbrev;
    this.actions = [];
    this.optionStringActions = new Map();
    if (add_help) {
      this.add_argument('-h', '--help', {
        action: 'help',
        help: 'show this help message and exit',
      });
    }
  }

  /** 用法与 Python 一致：先若干个选项串，最后一个可选的配置对象。 */
  add_argument(...args) {
    const config = typeof args[args.length - 1] === 'object' ? args.pop() : {};
    const optionStrings = args;
    if (optionStrings.length === 0) {
      throw new ValueError('only optional arguments are supported');
    }
    const longest = optionStrings.find((option) => option.startsWith('--')) ?? optionStrings[0];
    const dest = config.dest ?? longest.replace(/^-+/, '').replace(/-/g, '_');
    const action = new Action({ optionStrings, dest, ...config });
    this.actions.push(action);
    for (const option of optionStrings) this.optionStringActions.set(option, action);
    return action;
  }

  format_usage() {
    const parts = this.actions.map((action) => {
      const invocation = action.formatInvocation(false);
      return action.required ? invocation : `[${invocation}]`;
    });
    return `usage: ${[this.prog, ...parts].join(' ')}\n`;
  }

  format_help() {
    let text = this.format_usage();
    if (this.description) text += `\n${this.description}\n`;

    const invocations = this.actions.map((action) => action.formatInvocation(true));
    const actionMaxLength = Math.max(...invocations.map((item) => item.length + 2));
    const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);
    const actionWidth = helpPosition - 4;

    text += '\noptions:\n';
    this.actions.forEach((action, index) => {
      const invocation = invocations[index];
      if (!action.help) {
        text += `  ${invocation}\n`;
      } else if (invocation.length <= actionWidth) {
        text += `  ${invocation.padEnd(actionWidth)}  ${action.help}\n`;
      } else {
        text += `  ${invocation}\n${' '.repeat(helpPosition)}${action.help}\n`;
      }
    });
    return text;
  }

  print_help() {
    writeStdout(this.format_help());
  }

  error(message) {
    writeStderr(this.format_usage());
    writeStderr(`${this.prog}: error: ${message}\n`);
    exit(2);
  }

  /** 判断一个命令行片段是不是选项（负数、单个 '-'、含空格的都算取值）。 */
  _looksLikeOption(arg) {
    if (!arg.startsWith('-')) return false;
    if (this.optionStringActions.has(arg)) return true;
    if (arg.length === 1) return false;
    if (arg.includes('=')) return true;
    if (NEGATIVE_NUMBER.test(arg)) return false;
    if (arg.includes(' ')) return false;
    return true;
  }

  /** 精确匹配优先，其次是唯一前缀缩写；都不中则视为未知选项。 */
  _resolveOption(option) {
    if (this.optionStringActions.has(option)) return this.optionStringActions.get(option);
    if (!this.allowAbbrev || !option.startsWith('--')) return null;
    const matches = [...this.optionStringActions.keys()].filter((known) =>
      known.startsWith(option),
    );
    const unique = new Set(matches.map((match) => this.optionStringActions.get(match)));
    if (unique.size === 1) return [...unique][0];
    if (unique.size > 1) {
      this.error(`ambiguous option: ${option} could match ${matches.join(', ')}`);
    }
    return null;
  }

  _convert(action, raw) {
    if (!action.type) return raw;
    try {
      return action.type(raw);
    } catch (err) {
      if (err instanceof ValueError) {
        const typeName = action.type.__name__ ?? action.type.name ?? 'value';
        this.error(`argument ${action.name}: invalid ${typeName} value: ${repr(raw)}`);
      }
      throw err;
    }
  }

  parse_args(argv = process.argv.slice(2)) {
    const [namespace, extras] = this.parse_known_args(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  parse_known_args(argv = process.argv.slice(2)) {
    const namespace = Object.create(null);
    for (const action of this.actions) {
      if (action.action === 'store') namespace[action.dest] = null;
    }

    const extras = [];
    const seen = new Set();
    let optionsTerminated = false;

    for (let index = 0; index < argv.length; index += 1) {
      const arg = argv[index];

      if (optionsTerminated || !this._looksLikeOption(arg)) {
        if (arg === '--' && !optionsTerminated) optionsTerminated = true;
        extras.push(arg);
        continue;
      }

      let option = arg;
      let explicitValue = null;
      const equals = arg.indexOf('=');
      if (arg.startsWith('--') && equals > -1) {
        option = arg.slice(0, equals);
        explicitValue = arg.slice(equals + 1);
      }

      const action = this._resolveOption(option);
      if (action === null) {
        extras.push(arg);
        continue;
      }

      if (action.action === 'help') {
        this.print_help();
        exit(0);
      }

      if (action.action === 'store_true') {
        namespace[action.dest] = true;
        seen.add(action);
        continue;
      }

      let raw = explicitValue;
      if (raw === null) {
        const next = argv[index + 1];
        if (next === undefined || this._looksLikeOption(next)) {
          this.error(`argument ${action.name}: expected one argument`);
        }
        raw = next;
        index += 1;
      }
      namespace[action.dest] = this._convert(action, raw);
      seen.add(action);
    }

    const missing = this.actions.filter((action) => action.required && !seen.has(action));
    if (missing.length > 0) {
      this.error(
        `the following arguments are required: ${missing.map((action) => action.name).join(', ')}`,
      );
    }

    return [namespace, extras];
  }
}

