import { PyException, ValueError } from '../python/errors.mjs';

export class ScheduleError extends PyException {
  static pyName = 'ScheduleError';
}

export class ScheduleValueError extends ScheduleError {
  static pyName = 'ScheduleValueError';
}

export class IntervalError extends ScheduleValueError {
  static pyName = 'IntervalError';
}

export { ValueError };

