/**
 * Scheduler：作业容器，负责创建 Job 并保存已登记的作业。
 */

import { DateTime } from '../python/datetime.mjs';
import { Job } from './job.mjs';

export class Scheduler {
  constructor() {
    /** @type {Job[]} */
    this.jobs = [];
  }

  /** 新建一个间隔为 interval 的作业（尚未指定时间单位）。 */
  every(interval = 1n) {
    return new Job(typeof interval === 'bigint' ? interval : BigInt(interval), this);
  }

  /** 返回作业列表的副本；给定标签时只返回带该标签的作业。 */
  get_jobs(tag = null) {
    if (tag === null) return this.jobs.slice();
    return this.jobs.filter((job) => job.tags.has(tag));
  }

  /** 删除作业；不给标签则清空全部。 */
  clear(tag = null) {
    if (tag === null) {
      this.jobs = [];
      return;
    }
    this.jobs = this.jobs.filter((job) => !job.tags.has(tag));
  }

  cancel_job(job) {
    const index = this.jobs.indexOf(job);
    if (index !== -1) this.jobs.splice(index, 1);
  }

  /** 运行所有到点的作业。 */
  run_pending() {
    const runnable = this.jobs.filter((job) => job.should_run).sort((a, b) => a.next_run.compare(b.next_run));
    for (const job of runnable) this._run_job(job);
  }

  run_all(delay_seconds = 0) {
    for (const job of this.jobs.slice()) this._run_job(job);
    return delay_seconds;
  }

  _run_job(job) {
    const result = job.run();
    if (result === CancelJob || result instanceof CancelJob) this.cancel_job(job);
  }

  get next_run() {
    if (this.jobs.length === 0) return null;
    return this.jobs.reduce((soonest, job) =>
      job.next_run.compare(soonest.next_run) < 0 ? job : soonest,
    ).next_run;
  }

  get idle_seconds() {
    const next = this.next_run;
    if (next === null) return null;
    return next.diff(DateTime.now()).totalSeconds();
  }
}

/** 作业回调返回它即表示注销自己。 */
export class CancelJob {}

