1	/**
2	 * CPython 回溯文本的复现。
3	 *
4	 * 异常向外传播时，每一层调用把自己的帧插到最前面，最终按
5	 * "most recent call last" 的顺序渲染。被 PyInstaller 打包的脚本里，
6	 * 只有入口脚本带源码行（因而有源码文本和 `^^^` 定位标记），
7	 * 第三方库的帧只有 File / line / 函数名。
8	 */
9	
10	import { readFileSync } from 'node:fs';
11	import { formatExceptionOnly, isPyException } from './errors.mjs';
12	import { exit, writeStderr } from './io.mjs';
13	
14	/**
15	 * linecache：回溯里的源码行是运行时按帧记录的路径去读的（相对当前工作
16	 * 目录）。打包后的程序通常找不到源码文件，于是只剩 File/line 一行 ——
17	 * 这也是为什么同一个错误在不同目录下运行会有不同的回溯长度。
18	 */
19	const sourceCache = new Map();
20	
21	function getSourceLine(file, lineno) {
22	  if (!sourceCache.has(file)) {
23	    let lines = null;
24	    try {
25	      lines = readFileSync(file, 'utf8').split('\n');
26	    } catch {
27	      lines = null;
28	    }
29	    sourceCache.set(file, lines);
30	  }
31	  const lines = sourceCache.get(file);
32	  if (lines === null || lineno < 1 || lineno > lines.length) return null;
33	  return lines[lineno - 1];
34	}
35	
36	/** 构造入口脚本的调用帧：列区间由语句文本与其中的子表达式推出。 */
37	export function sourceFrame({ file, func, line, code, expr }) {
38	  const colStart = code === undefined || expr === undefined ? undefined : code.indexOf(expr);
39	  return {
40	    file,
41	    func,
42	    line,
43	    colStart,
44	    colEnd: colStart === undefined ? undefined : colStart + expr.length,
45	  };
46	}
47	
48	/** 把一个调用帧记到异常上（越外层越先被渲染）。 */
49	export function addFrame(err, frame) {
50	  if (isPyException(err)) err.pyTraceback.unshift(frame);
51	  return err;
52	}
53	
54	/** 在指定帧的上下文中执行；异常穿过时自动补上该帧。 */
55	export function atFrame(frame, body) {
56	  try {
57	    return body();
58	  } catch (err) {
59	    throw addFrame(err, frame);
60	  }
61	}
62	
63	export function formatTraceback(err) {
64	  let text = 'Traceback (most recent call last):\n';
65	  for (const frame of err.pyTraceback) {
66	    text += `  File "${frame.file}", line ${frame.line}, in ${frame.func}\n`;
67	
68	    const raw = getSourceLine(frame.file, frame.line);
69	    if (raw === null) continue;
70	    const stripped = raw.trim();
71	    text += `    ${stripped}\n`;
72	
73	    if (frame.colStart === undefined) continue;
74	    const indent = raw.length - raw.trimStart().length;
75	    const start = frame.colStart - indent;
76	    const width = frame.colEnd - frame.colStart;
77	    // 定位标记覆盖整行时 CPython 会省略它
78	    if (start < 0 || width <= 0 || (start === 0 && width >= stripped.length)) continue;
79	    text += `${' '.repeat(4 + start)}${'^'.repeat(width)}\n`;
80	  }
81	  return text + formatExceptionOnly(err) + '\n';
82	}
83	
84	/**
85	 * 未捕获异常时的终止流程：回溯写 stderr，再补一行 PyInstaller 的提示，
86	 * 退出码 1。
87	 */
88	export function dieWithTraceback(err, scriptName) {
89	  writeStderr(formatTraceback(err));
90	  writeStderr(
91	    `[PYI-${process.pid}:ERROR] Failed to execute script '${scriptName}' due to unhandled exception!\n`,
92	  );
93	  exit(1);
94	}
