 * "most recent call last" 的顺序渲染。被 PyInstaller 打包的脚本里，
 * 只有入口脚本带源码行（因而有源码文本和 `^^^` 定位标记），
 * 第三方库的帧只有 File / line / 函数名。
 */

import { readFileSync } from 'node:fs';
import { formatExceptionOnly, isPyException } from './errors.mjs';
import { exit, writeStderr } from './io.mjs';

/**
 * linecache：回溯里的源码行是运行时按帧记录的路径去读的（相对当前工作
 * 目录）。打包后的程序通常找不到源码文件，于是只剩 File/line 一行 ——
 * 这也是为什么同一个错误在不同目录下运行会有不同的回溯长度。
 */
const sourceCache = new Map();

function getSourceLine(file, lineno) {
  if (!sourceCache.has(file)) {
    let lines = null;
    try {
      lines = readFileSync(file, 'utf8').split('\n');
    } catch {
      lines = null;
    }
    sourceCache.set(file, lines);
  }
  const lines = sourceCache.get(file);
  if (lines === null || lineno < 1 || lineno > lines.length) return null;
  return lines[lineno - 1];
}

/** 构造入口脚本的调用帧：列区间由语句文本与其中的子表达式推出。 */
export function sourceFrame({ file, func, line, code, expr }) {
  const colStart = code === undefined || expr === undefined ? undefined : code.indexOf(expr);
  return {
    file,
    func,
    line,
    colStart,
    colEnd: colStart === undefined ? undefined : colStart + expr.length,
  };
}

/** 把一个调用帧记到异常上（越外层越先被渲染）。 */
export function addFrame(err, frame) {
  if (isPyException(err)) err.pyTraceback.unshift(frame);
  return err;
}

/** 在指定帧的上下文中执行；异常穿过时自动补上该帧。 */
export function atFrame(frame, body) {
  try {
    return body();
  } catch (err) {
    throw addFrame(err, frame);
  }
}

export function formatTraceback(err) {
  let text = 'Traceback (most recent call last):\n';
  for (const frame of err.pyTraceback) {
    text += `  File "${frame.file}", line ${frame.line}, in ${frame.func}\n`;

    const raw = getSourceLine(frame.file, frame.line);
    if (raw === null) continue;
    const stripped = raw.trim();
    text += `    ${stripped}\n`;

    if (frame.colStart === undefined) continue;
    const indent = raw.length - raw.trimStart().length;
    const start = frame.colStart - indent;
    const width = frame.colEnd - frame.colStart;
    // 定位标记覆盖整行时 CPython 会省略它
    if (start < 0 || width <= 0 || (start === 0 && width >= stripped.length)) continue;
    text += `${' '.repeat(4 + start)}${'^'.repeat(width)}\n`;
  }
  return text + formatExceptionOnly(err) + '\n';
}

/**
 * 未捕获异常时的终止流程：回溯写 stderr，再补一行 PyInstaller 的提示，
 * 退出码 1。
 */
export function dieWithTraceback(err, scriptName) {
  writeStderr(formatTraceback(err));
  writeStderr(
    `[PYI-${process.pid}:ERROR] Failed to execute script '${scriptName}' due to unhandled exception!\n`,
  );
  exit(1);
}

