/**
 * Job：一个待调度的作业。
 *
 * 链式写法 `every(5).seconds.do(fn)` 的每一步都对应这里的一个属性 getter，
 * getter 只改写 unit / start_day 并把 this 传下去，真正的时间计算发生在
 * do() 里的 _schedule_next_run()。
 *
 * _schedule_next_run() 的三处失败点与 CPython 侧的行号一一对应，
 * 便于在异常时复现回溯（详见 lib/python/traceback.mjs）：
 *   line 729 —— 构造 timedelta
 *   line 731 —— now + period
 *   line 734 —— 循环推进直到 next_run 超过 now（间隔非正时无法收敛）
 */

import { DateTime, TimeDelta } from '../python/datetime.mjs';
import { partial, update_wrapper } from '../python/functools.mjs';
import { repr } from '../python/repr.mjs';
import { addFrame } from '../python/traceback.mjs';
import { IntervalError, ScheduleError, ScheduleValueError } from './errors.mjs';

const VALID_UNITS = ['seconds', 'minutes', 'hours', 'days', 'weeks'];
const WEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];

const SCHEDULE_MODULE = 'schedule/__init__.py';
const FRAME_DO = { file: SCHEDULE_MODULE, line: 657, func: 'do' };
const framePeriod = { file: SCHEDULE_MODULE, line: 729, func: '_schedule_next_run' };
const frameFirstRun = { file: SCHEDULE_MODULE, line: 731, func: '_schedule_next_run' };
const frameAdvance = { file: SCHEDULE_MODULE, line: 734, func: '_schedule_next_run' };

/** `random.randint(a, b)`：闭区间取整数。 */
function randint(low, high) {
  const span = Number(high - low) + 1;
  return low + BigInt(Math.floor(Math.random() * span));
}

export class Job {
  constructor(interval, scheduler = null) {
    this.interval = interval;
    this.latest = null;
    this.job_func = null;
    this.unit = null;
    this.at_time = null;
    this.last_run = null;
    this.next_run = null;
    this.period = null;
    this.start_day = null;
    this.tags = new Set();
    this.scheduler = scheduler;
  }

  _requireUnitInterval(singular, plural) {
    if (this.interval !== 1n) {
      throw new IntervalError(`Use ${plural} instead of ${singular}`);
    }
  }

  _requireWeeklyInterval(day) {
    if (this.interval !== 1n) {
      throw new IntervalError(
        `Scheduling .${day}() jobs is only allowed for weekly jobs. ` +
          `Using .${day}() on a job scheduled to run every 2 or more weeks ` +
          'is not supported.',
      );
    }
  }

  get second() {
    this._requireUnitInterval('second', 'seconds');
    return this.seconds;
  }

  get seconds() {
    this.unit = 'seconds';
    return this;
  }

  get minute() {
    this._requireUnitInterval('minute', 'minutes');
    return this.minutes;
  }

  get minutes() {
    this.unit = 'minutes';
    return this;
  }

  get hour() {
    this._requireUnitInterval('hour', 'hours');
    return this.hours;
  }

  get hours() {
    this.unit = 'hours';
    return this;
  }

  get day() {
    this._requireUnitInterval('day', 'days');
    return this.days;
  }

  get days() {
    this.unit = 'days';
    return this;
  }

  get week() {
    this._requireUnitInterval('week', 'weeks');
    return this.weeks;
  }

  get weeks() {
    this.unit = 'weeks';
    return this;
  }

  get monday() {
    this._requireWeeklyInterval('monday');
    this.start_day = 'monday';
    return this.weeks;
  }

  get tuesday() {
    this._requireWeeklyInterval('tuesday');
    this.start_day = 'tuesday';
    return this.weeks;
  }

  get wednesday() {
    this._requireWeeklyInterval('wednesday');
    this.start_day = 'wednesday';
    return this.weeks;
  }

  get thursday() {
    this._requireWeeklyInterval('thursday');
    this.start_day = 'thursday';
    return this.weeks;
  }

  get friday() {
    this._requireWeeklyInterval('friday');
    this.start_day = 'friday';
    return this.weeks;
  }

  get saturday() {
    this._requireWeeklyInterval('saturday');
    this.start_day = 'saturday';
    return this.weeks;
  }

  get sunday() {
    this._requireWeeklyInterval('sunday');
    this.start_day = 'sunday';
    return this.weeks;
  }

  /** 给作业打标签，返回自身以便继续链式调用。 */
  tag(...tags) {
    for (const item of tags) this.tags.add(item);
    return this;
  }

  /** 绑定回调、算出首次运行时间，并把自己登记到调度器里。 */
  do(job_func, ...args) {
    this.job_func = update_wrapper(partial(job_func, args), job_func);
    try {
      this._schedule_next_run();
    } catch (err) {
      throw addFrame(err, FRAME_DO);
    }
    if (this.scheduler === null) {
      throw new ScheduleError(
        'Unable to a add job to schedule. Job is not associated with an scheduler',
      );
    }
    this.scheduler.jobs.push(this);
    return this;
  }

  _schedule_next_run() {
    if (!VALID_UNITS.includes(this.unit)) {
      throw new ScheduleValueError(
        'Invalid unit (valid units are `seconds`, `minutes`, `hours`, `days`, and `weeks`)',
      );
    }

    let interval = this.interval;
    if (this.latest !== null) {
      if (!(this.latest >= this.interval)) {
        throw new ScheduleError('`latest` is greater than `interval`');
      }
      interval = randint(this.interval, this.latest);
    }

    try {
      this.period = TimeDelta.of({ [this.unit]: interval });
    } catch (err) {
      throw addFrame(err, framePeriod);
    }

    const now = DateTime.now();
    try {
      this.next_run = now.plus(this.period);
    } catch (err) {
      throw addFrame(err, frameFirstRun);
    }

    if (this.start_day !== null) {
      if (this.unit !== 'weeks') {
        throw new ScheduleValueError("`unit` should be 'weeks'");
      }
      if (!WEEKDAYS.includes(this.start_day)) {
        throw new ScheduleValueError(
          `Invalid start day (valid start days are ${repr(WEEKDAYS)})`,
        );
      }
      let daysAhead = WEEKDAYS.indexOf(this.start_day) - this.next_run.weekday();
      if (daysAhead <= 0) daysAhead += 7;
      this.next_run = this.next_run
        .plus(TimeDelta.of({ days: daysAhead }))
        .minus(this.period);
    }

    // 间隔为正时循环体一次都不会执行；为零则永不收敛，为负则一路回退到
    // datetime 下界并抛出 OverflowError —— 与 CPython 侧表现一致。
    try {
      while (this.next_run.lessOrEqual(now)) {
        this.next_run = this.next_run.plus(this.period);
      }
    } catch (err) {
      throw addFrame(err, frameAdvance);
    }
  }

  /** 是否到了该运行的时间。 */
  get should_run() {
    return this.next_run !== null && DateTime.now().compare(this.next_run) >= 0;
  }

  run() {
    const result = this.job_func();
    this.last_run = DateTime.now();
    this._schedule_next_run();
    return result;
  }

  __str__() {
    const name =
      this.job_func === null ? 'None' : this.job_func.__name__ ?? repr(this.job_func);
    const args = this.job_func === null ? '()' : repr(this.job_func.args);
    const kwargs = this.job_func === null ? '{}' : repr(this.job_func.keywords);
    return `Job(interval=${this.interval}, unit=${this.unit}, do=${name}, args=${args}, kwargs=${kwargs})`;
  }
}
